  '{"must":[],"must_not":[]}'::jsonb, '["structured-output"]'::jsonb, 'ai', 'anthropic', 'claude-opus-5', 8000, 0, 'platform'),

 ('nl-feature-benefits-intent', 'Map Features to Benefits', 'intent',
  $q$Turn each shipped ticket into the benefit a buyer would repeat, with its proof.$q$,
  $q$Your task_context carries the shipped backlog rows since the last map, the existing feature_benefit records, the customer_profile record and the corrections. For each shipped ticket a buyer would notice: what they can do now that they could not before, who it helps, and the proof (the ticket id plus a measured number where one exists). Skip internal plumbing a buyer would never see, and say how many were skipped. Update an existing record rather than duplicating it. Return records_to_write: one feature_benefit record each, status draft. Napkin entries you are given rank above web research (THE NAPKIN RULE): cite them [napkin:<entry id>], list each one you used in napkin_notes with a single line saying what you did with it and which record it became, and list the rest in napkin_left untouched.$q$,
