  '{"must":[],"must_not":[]}'::jsonb, '["structured-output","web-search"]'::jsonb, 'ai', 'anthropic', 'claude-opus-5', 10000, 0, 'platform'),

 ('nl-release-notes-intent', 'Write the Release Notes', 'intent',
  $q$Write customer-facing release notes for shipped tickets, in plain words.$q$,
  $q$Your task_context carries the shipped backlog rows for the period, the feature_benefit and release_note records, and the corrections. For each ticket a customer would notice: a headline under ten words, what the customer can do now in one or two sentences, and who it helps. Leave out internal plumbing and say how many tickets were left out. No jargon, no ticket-internal terms, no promise of future work. Return records_to_write: one release_note record each, status draft. Napkin entries you are given rank above web research (THE NAPKIN RULE): cite them [napkin:<entry id>], list each one you used in napkin_notes with a single line saying what you did with it and which record it became, and list the rest in napkin_left untouched.$q$,
