-- Links: the four shared Skills to every pmm-* Capability, and each Intent to its own ----------------------------------------------
INSERT INTO public.capability_skill_profiles (capability_slug, skill_profile_slug, level, is_required, display_order)
SELECT c.slug, s.slug, 2, true, s.ord
FROM public.capabilities c
CROSS JOIN (VALUES ('nl-identity', 1), ('nl-knowledge-method', 2), ('nl-behavior', 3), ('nl-guardrails', 6)) AS s(slug, ord)
WHERE c.slug LIKE 'pmm-%';

INSERT INTO public.capability_skill_profiles (capability_slug, skill_profile_slug, level, is_required, display_order)
SELECT c.slug, c.default_intent_slug, 2, true, 4
FROM public.capabilities c WHERE c.slug LIKE 'pmm-%';

-- Assertions: 1 agent, 11 capabilities, 11 assignments, 15 skills, 55 links; knowledge inline; career_records only forbidden;
-- no row names another agent.
DO $$
DECLARE n int; bad text;
BEGIN
  SELECT count(*) INTO n FROM public.agents WHERE id = 'nathan' AND lane = 'product' AND is_active = false; IF n <> 1 THEN RAISE EXCEPTION 'agent row: %', n; END IF;
  SELECT count(*) INTO n FROM public.capabilities WHERE slug LIKE 'pmm-%'; IF n <> 11 THEN RAISE EXCEPTION 'capabilities: %', n; END IF;
  SELECT count(*) INTO n FROM public.agent_capability_assignments WHERE agent_id = 'nathan'; IF n <> 11 THEN RAISE EXCEPTION 'assignments: %', n; END IF;
  SELECT count(*) INTO n FROM public.skill_profiles WHERE slug LIKE 'nl-%'; IF n <> 15 THEN RAISE EXCEPTION 'skills: %', n; END IF;
  SELECT count(*) INTO n FROM public.capability_skill_profiles WHERE capability_slug LIKE 'pmm-%'; IF n <> 55 THEN RAISE EXCEPTION 'links: %', n; END IF;
  SELECT count(*) INTO n FROM public.capabilities c LEFT JOIN public.skill_profiles s ON s.slug = c.default_intent_slug AND s.skill_type_slug = 'intent' WHERE c.slug LIKE 'pmm-%' AND s.slug IS NULL; IF n <> 0 THEN RAISE EXCEPTION 'capability without its intent: %', n; END IF;
  SELECT count(*) INTO n FROM public.skill_profiles WHERE slug LIKE 'nl-%' AND skill_type_slug = 'knowledge' AND coalesce(traits->>'source','') <> 'inline'; IF n <> 0 THEN RAISE EXCEPTION 'knowledge not inline: %', n; END IF;
  SELECT count(*) INTO n FROM public.skill_profiles WHERE slug LIKE 'nl-%' AND slug <> 'nl-guardrails' AND (coalesce(method,'') || coalesce(objective,'') || traits::text || guardrails::text) ~* 'career_records'; IF n <> 0 THEN RAISE EXCEPTION 'career_records named outside the guardrails: %', n; END IF;
  SELECT string_agg(s.slug || '~' || a.id, ', ') INTO bad
    FROM public.skill_profiles s JOIN public.agents a ON a.id <> 'nathan'
   WHERE s.slug LIKE 'nl-%' AND (coalesce(s.method,'') || coalesce(s.objective,'') || coalesce(s.description,'') || s.traits::text || s.guardrails::text) ~* ('\m' || a.id || '\M');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'an nl row names another agent: %', bad; END IF;
  SELECT string_agg(c.slug || '~' || a.id, ', ') INTO bad
    FROM public.capabilities c JOIN public.agents a ON a.id <> 'nathan'
   WHERE c.slug LIKE 'pmm-%' AND (c.name || ' ' || coalesce(c.description,'') || ' ' || coalesce(c.display_phrase,'')) ~* ('\m' || a.id || '\M');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'a pmm capability names another agent: %', bad; END IF;
END $$;

COMMIT;
